<include file="Public:header"/><div class="mainbox">	<div id="nav" class="mainnav_title">		<ul>			<a href="{pigcms{:U('Recruit/course_list')}" class="on">视频列表</a>|			<a href="{pigcms{:U('Recruit/course_commend')}">评论列表</a>|			<a href="{pigcms{:U('Recruit/course_category')}">分类列表</a>		</ul>	</div>    <table class="search_table" width="100%">        <tr>            <td>                <form action="{pigcms{:U('Recruit/company_list')}" method="get">                    <input type="hidden" name="c" value="Recruit"/>                    <input type="hidden" name="a" value="course_list"/>                    筛选: <input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>                    <select name="type">                        <option value="title" <if condition="$_GET['type'] eq 'title'">selected="selected"</if>>标题</option>                        <option value="name" <if condition="$_GET['type'] eq 'name'">selected="selected"</if>>用户昵称</option>                    </select>                    <input type="submit" value="查询" class="button"/>                </form>            </td>        </tr>    </table>	<form name="myform" id="myform" action="" method="post">		<div class="table-list">			<table width="100%" cellspacing="0">				<colgroup>					<col/>					<col/>					<col/>					<col/>					<col/>					<col/>					<col/>					<col/>					<col/>					<col  align="center"/>				</colgroup>				<thead>					<tr>						<th>编号</th>						<th>标题</th>						<th>分类</th>						<th>查看所需积分</th>						<th>状态</th>						<th>申请时间</th>						<th>审核时间</th>						<th>操作</th>					</tr>				</thead>				<tbody>					<if condition="$list['list']">						<volist name="list.list" id="vo">							<tr>								<td>{pigcms{$vo.course_id}</td>								<td>{pigcms{$vo.title}</td>								<td>{pigcms{$vo.cat_name}</td>								<td>{pigcms{$vo.score}</td>								<td>                                <if condition="$vo['status'] eq 0">                                	<span style="color: orange;">待审核</span>                                <elseif condition="$vo['status'] eq 1"/>                                	<span style="color: green;">审核通过</span>                                <elseif condition="$vo['status'] eq 2"/>                                	<span style="color: red;">审核不通过</span>                                </if>                            	</td>                                <td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>                                <td><if condition="$vo['status'] eq 0">未审核<else/>{pigcms{$vo.audit_time|date='Y-m-d H:i:s',###}</if></td>								<td>									<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('course_edit',array('course_id'=>$vo['course_id']))}','编辑',800,600,true,false,false,editbtn,'edit',true);">编辑</a>|									<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('course_audit',array('course_id'=>$vo['course_id']))}','审核',800,600,true,false,false,editbtn,'edit',true);">审核</a>|									<a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.course_id}" url="{pigcms{:U('course_del')}">删除</a>							  	</td>							</tr>						</volist>						<tr><td class="textcenter pagebar" colspan="10">{pigcms{$list.pagebar}</td></tr>					<else/>						<tr><td class="textcenter red" colspan="10">列表为空！</td></tr>					</if>				</tbody>			</table>		</div>	</form></div><include file="Public:footer"/>